# Generated by scripts/prepare-homebrew.py from the local crate archive.
class Rightcommit < Formula
  desc "Self-hosted, Rust-built orchestration for Claude Code, Codex and Pi Agent"
  homepage "https://rightcommit.com"
  url "https://static.crates.io/crates/rightcommit/rightcommit-1.7.1.crate"
  version "1.7.1"
  sha256 "86ea0f8cbd8aa3d0d6ad2439ea3b4bfa391513ed2591b8faf47770b2fef310f5"
  license "Apache-2.0"

  bottle do
    root_url "https://github.com/rightcommit/homebrew-tap/releases/download/rightcommit-1.7.1"
    rebuild 1
    sha256 cellar: :any_skip_relocation, arm64_sequoia: "cd4faeedf5d237a7281a80dd5d9727a63a6a45ef1c0102d67ce52513825974f5"
  end

  depends_on "cmake" => :build
  depends_on "pkgconf" => :build
  depends_on "protobuf" => :build
  # Rust is not needed to run rightcommit: workflows on Rust projects use whichever cargo
  # comes first in PATH (rustup or Homebrew's, if the user keeps it).
  depends_on "rust" => :build
  depends_on "git"
  depends_on "node@24"
  depends_on "openssl@3"
  depends_on "python@3.14"
  depends_on "ripgrep"

  def install
    system "cargo", "install", *std_cargo_args(path: ".", root: libexec)
    (bin/"rightcommit").write <<~SH
      #!/bin/bash
      export PATH="#{Formula["node@24"].opt_bin}:$PATH"
      exec "#{libexec}/bin/rightcommit" "$@"
    SH
    chmod 0755, bin/"rightcommit"
  end

  def caveats
    <<~EOS
      Start from a writable directory:
        mkdir -p ~/rightcommit && cd ~/rightcommit
        rightcommit setup
        rightcommit
      Open http://localhost:8080. Data stays in ./data.
      Run setup again after upgrading to refresh the agents.

      If Homebrew compiled rightcommit (Intel Macs, macOS before 15), it installed Rust
      only for that: `brew autoremove` removes it.
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/rightcommit --version")
    port = free_port
    pid = spawn({"NODO_LISTEN" => "127.0.0.1:#{port}"}, bin/"rightcommit")
    begin
      system "curl", "--fail", "--retry", "15", "--retry-connrefused",
        "--retry-delay", "1", "http://127.0.0.1:#{port}/healthz"
      assert_path_exists testpath/"data/system/assets"
    ensure
      Process.kill("INT", pid)
      Process.wait(pid)
    end
  end
end
